def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True

def unique_in_order(values: list[int]) -> list[int]:
    """Keep the first occurrence of each number, preserving order."""
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

def average(values: list[float]) -> float:
    """Return the arithmetic mean, or zero for an empty input."""
    if not values:
        return 0.0
    total = sum(values)
    return total / len(values)

def histogram(words: list[str]) -> dict[str, int]:
    counts = {}
    for word in words:
        normalized = word.strip().lower()
        if not normalized:
            continue
        counts[normalized] = counts.get(normalized, 0) + 1
    return counts

def binary_search(values: list[int], target: int) -> int:
    left, right = 0, len(values) - 1
    while left <= right:
        middle = (left + right) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle - 1
    return -1

def clamp(value: float, low: float, high: float) -> float:
    if low > high:
        raise ValueError("invalid interval")
    if value < low:
        return low
    if value > high:
        return high
    return value

def nonempty_lines(document: str) -> list[str]:
    result = []
    for line in document.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        result.append(line)
    return result

#include <vector>
#include <stdexcept>
double dot_product(const std::vector<double>& a, const std::vector<double>& b) {
    if (a.size() != b.size()) throw std::invalid_argument("size mismatch");
    double result = 0.0;
    for (std::size_t i = 0; i < a.size(); ++i) {
        result += a[i] * b[i];
    }
    return result;
}

#include <vector>
#include <cstddef>
std::size_t count_positive(const std::vector<int>& data) {
    std::size_t count = 0;
    for (int value : data) {
        if (value > 0) {
            ++count;
        }
    }
    return count;
}

#include <vector>
#include <stdexcept>
int maximum(const std::vector<int>& values) {
    if (values.empty()) throw std::invalid_argument("empty input");
    int best = values.front();
    for (int value : values) {
        if (value > best) best = value;
    }
    return best;
}

#include <vector>
std::vector<int> even_values(const std::vector<int>& input) {
    std::vector<int> output;
    for (int value : input) {
        if (value % 2 == 0) output.push_back(value);
    }
    return output;
}

#include <vector>
std::vector<int> prefix_sums(const std::vector<int>& data) {
    std::vector<int> result;
    int running = 0;
    for (int value : data) {
        running += value;
        result.push_back(running);
    }
    return result;
}

#include <cmath>
struct Point { double x; double y; };
double distance(Point a, Point b) {
    const double dx = a.x - b.x;
    const double dy = a.y - b.y;
    return std::sqrt(dx * dx + dy * dy);
}
